package dev.pixel.backgroundcontrol;
import android.app.Activity;import android.os.*;import android.widget.*;import java.lang.ref.WeakReference;
public final class MainActivity extends Activity {
 static WeakReference<MainActivity> visible=new WeakReference<>(null);final Handler h=new Handler();TextView status,result;
 // The last button's outcome (#225) lives apart from status, which the refresh below rewrites every 500 ms.
 final ActionNotice notice=new ActionNotice();
 final Runnable refresh=new Runnable(){public void run(){try{status.setText(Controller.state(MainActivity.this).toString(2));}catch(Exception ignored){}h.postDelayed(this,500);}};
 void show(){result.setText(notice.text());}
 public void onCreate(Bundle b){super.onCreate(b);if(b!=null)notice.restore(b.getString(ActionNotice.SAVED_KEY));LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,36,24,24);TextView title=new TextView(this);title.setText("Rose Agent background control");title.setTextSize(24);l.addView(title);TextView help=new TextView(this);help.setText("Apps run on a separate background display. Android may require consent before a session starts.");l.addView(help);Button consent=new Button(this);consent.setText("Continue Android consent");consent.setOnClickListener(v->{try{notice.consent(Controller.requestConsent(this));}catch(Exception e){notice.failed("Android consent",e);}show();});l.addView(consent);Button viewer=new Button(this);viewer.setText("Show floating agent view");viewer.setOnClickListener(v->{try{startActivity(new android.content.Intent(this,AgentPipActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));}catch(RuntimeException e){notice.failed("Floating agent view",e);show();}});l.addView(viewer);Button stop=new Button(this);stop.setText("Stop background session");stop.setOnClickListener(v->{try{Controller.stop(this,StopLedger.USER);org.json.JSONObject s=Controller.state(this);notice.stopped(s.optString("status"),s.optString("error"));}catch(Exception e){notice.failed("Reading the session after Stop",e);}show();});l.addView(stop);result=new TextView(this);result.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);l.addView(result);status=new TextView(this);l.addView(status);setContentView(l);show();}
 public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString(ActionNotice.SAVED_KEY,notice.text());}
 public void onResume(){super.onResume();visible=new WeakReference<>(this);h.post(refresh);}public void onPause(){h.removeCallbacks(refresh);visible.clear();super.onPause();}
}
